#!/usr/bin/env node
// Builds the blog from markdown. Zero dependencies — needs Node 18+.
//
//   blog/posts/<slug>.md   →   blog/<slug>.html   (+ blog/index.html, blog/feed.xml)
//   and the "Latest writing" section on the homepage (between the blog:latest markers in index.html)
//
// Run `node build-blog.mjs`, commit the generated files, push. See README.md.
// A post can be plain markdown: `# Title`, an optional `_subtitle_` line, then the body. Frontmatter is optional
// and overrides what is derived (title, summary, date, tags). No date = the day it is built.
//   --stamp   write the build date into any post that has none (CI runs this on merge, so a post's
//             date is the day it was merged and never changes again)
//   --drafts  include `draft: true` posts (local preview only; don't commit)

import { readFileSync, writeFileSync, readdirSync, existsSync, unlinkSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = dirname(fileURLToPath(import.meta.url));
const SITE = 'https://kaibinw.github.io';
const POSTS = join(ROOT, 'blog', 'posts');
const OUT = join(ROOT, 'blog');
const MARK = '<!-- generated by build-blog.mjs — edit blog/posts/*.md, not this file -->';
const LATEST = 3; // posts shown on the homepage
const withDrafts = process.argv.includes('--drafts');
const stamp = process.argv.includes('--stamp');
const TODAY = new Intl.DateTimeFormat('en-CA', { timeZone: 'Australia/Brisbane' }).format(new Date());
const blogConfig = existsSync(join(OUT, 'config.json')) ? JSON.parse(readFileSync(join(OUT, 'config.json'), 'utf8')) : {};

// ---------- markdown ----------

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const slugify = (s) => s.toLowerCase().replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

function inline(s) {
  const codes = [];
  s = s.replace(/`([^`]+)`/g, (_, c) => `\u0000${codes.push(c) - 1}\u0000`);
  s = esc(s);
  s = s.replace(/!\[([^\]]*)\]\(([^)\s]+)(?:\s+&quot;(.*?)&quot;)?\)/g,
    (_, alt, src, title) => `<img src="${src}" alt="${alt}" loading="lazy"${title ? ` title="${title}"` : ''}>`);
  s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_, t, h) => `<a href="${h}"${/^https?:/.test(h) ? ' rel="noopener"' : ''}>${t}</a>`);
  s = s.replace(/&lt;(https?:\/\/[^\s&]+)&gt;/g, '<a href="$1" rel="noopener">$1</a>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
       .replace(/(^|[^*])\*([^*\s][^*]*)\*/g, '$1<em>$2</em>')
       .replace(/~~([^~]+)~~/g, '<del>$1</del>');
  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => `<code>${esc(codes[i])}</code>`);
}

const LIST = /^(\s*)([-*+]|\d+\.)\s+(.*)$/;
const FENCE = /^```\s*([\w+-]*)\s*$/;
const TABLE_SEP = /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/;
const isBlockStart = (l, next) =>
  /^#{1,6}\s/.test(l) || FENCE.test(l) || /^>/.test(l) || LIST.test(l) || /^(-{3,}|\*{3,})\s*$/.test(l) ||
  /^<[a-zA-Z]/.test(l) || (l.includes('|') && next !== undefined && TABLE_SEP.test(next));

function blocks(lines, ids) {
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    let m = line.match(FENCE);
    if (m) {
      const code = [];
      i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i])) code.push(lines[i++]);
      i++;
      out.push(`<pre><code${m[1] ? ` class="language-${m[1]}"` : ''}>${esc(code.join('\n'))}</code></pre>`);
      continue;
    }

    m = line.match(/^(#{1,6})\s+(.*?)\s*#*\s*$/);
    if (m) {
      const level = Math.max(2, m[1].length); // the post title is the page h1
      const html = inline(m[2]);
      let id = slugify(html) || 'section', n = 2;
      while (ids.has(id)) id = `${slugify(html)}-${n++}`;
      ids.add(id);
      out.push(`<h${level} id="${id}">${html}</h${level}>`);
      i++;
      continue;
    }

    if (/^(-{3,}|\*{3,})\s*$/.test(line)) { out.push('<hr>'); i++; continue; }

    if (/^>/.test(line)) {
      const q = [];
      while (i < lines.length && /^>/.test(lines[i])) q.push(lines[i++].replace(/^>\s?/, ''));
      out.push(`<blockquote>${blocks(q, ids)}</blockquote>`);
      continue;
    }

    if (/^<[a-zA-Z]/.test(line)) { // raw HTML block, passed through until a blank line
      const raw = [];
      while (i < lines.length && lines[i].trim()) raw.push(lines[i++]);
      out.push(raw.join('\n'));
      continue;
    }

    if (line.includes('|') && TABLE_SEP.test(lines[i + 1] ?? '')) {
      const cells = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => inline(c.trim()));
      const head = cells(line);
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) rows.push(cells(lines[i++]));
      out.push(`<table class="fact-table"><thead><tr>${head.map((c) => `<th>${c}</th>`).join('')}</tr></thead><tbody>` +
        rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('') + '</tbody></table>');
      continue;
    }

    m = line.match(LIST);
    if (m) {
      const base = m[1].length;
      const ordered = /\d/.test(m[2]);
      const items = [];
      while (i < lines.length) {
        const l = lines[i];
        const lm = l.match(LIST);
        if (lm && lm[1].length === base) {
          if (/\d/.test(lm[2]) !== ordered) break; // switching bullet ↔ numbered starts a new list
          items.push({ first: lm[3], rest: [] }); i++; continue;
        }
        if (!l.trim()) {
          const nxt = lines.slice(i + 1).find((x) => x.trim());
          if (nxt && (/^\s{2,}\S/.test(nxt) || (LIST.test(nxt) && nxt.match(LIST)[1].length >= base))) { i++; continue; }
          break;
        }
        if (/^\s+\S/.test(l) && (l.match(/^\s*/)[0].length > base)) { items.at(-1).rest.push(l); i++; continue; }
        break;
      }
      const tag = ordered ? 'ol' : 'ul';
      out.push(`<${tag}>` + items.map((it) => {
        const sub = it.rest.length ? blocks(dedent(it.rest), ids) : '';
        return `<li>${inline(it.first)}${sub}</li>`;
      }).join('') + `</${tag}>`);
      continue;
    }

    const p = [];
    while (i < lines.length && lines[i].trim() && !(p.length && isBlockStart(lines[i], lines[i + 1]))) p.push(lines[i++]);
    out.push(`<p>${inline(p.join(' ').trim())}</p>`);
  }
  return out.join('\n');
}

function dedent(lines) {
  const min = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^\s*/)[0].length));
  return lines.map((l) => l.slice(min));
}

const markdown = (src) => blocks(src.replace(/\r\n?/g, '\n').split('\n'), new Set());

// ---------- posts ----------

function slugFor(file, title) {
  const base = file.replace(/\.md$/, '');
  if (/^[a-z0-9]+(-[a-z0-9]+)*$/.test(base)) return base; // already a slug: keep the URL stable
  let s = slugify(title);
  if (s.length > 60) s = s.slice(0, 60).replace(/-[^-]*$/, '');
  return s;
}

function parsePost(file) {
  const raw = readFileSync(join(POSTS, file), 'utf8').replace(/\r\n?/g, '\n');
  const fm = raw.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  const meta = {};
  let body = raw;
  if (fm) {
    body = fm[2];
    for (const l of fm[1].split('\n')) {
      const kv = l.match(/^(\w+)\s*:\s*(.*)$/);
      if (kv) meta[kv[1]] = kv[2].trim().replace(/^(["'])(.*)\1$/, '$2');
    }
  }
  // plain-markdown posts: the leading "# Title" and "_subtitle_" feed the page header, so they leave the body
  const h1 = body.match(/^\s*# (.+?)\s*\n/);
  if (h1) {
    meta.title = meta.title || h1[1].trim();
    body = body.slice(h1[0].length);
    const sub = body.match(/^\s*(?:_([^_\n]+)_|\*([^*\n]+)\*)\s*\n/);
    if (sub) {
      meta.summary = meta.summary || (sub[1] || sub[2]).trim();
      body = body.slice(sub[0].length);
    }
  }
  if (!meta.title) throw new Error(`${file}: no title (start the file with "# Title" or add title: in frontmatter)`);
  if (!meta.summary) {
    const first = body.split(/\n\s*\n/).find((b) => b.trim() && !/^(#|```|[-*|>]|\d+\.)/.test(b.trim())) || '';
    const plain = first.replace(/[*_`]|\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/\s+/g, ' ').trim();
    meta.summary = plain.length > 180 ? plain.slice(0, 177).replace(/\s\S*$/, '') + '...' : plain;
  }
  const dateless = !meta.date;
  if (dateless) meta.date = TODAY;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(meta.date)) throw new Error(`${file}: date must be YYYY-MM-DD`);
  const draft = meta.draft === 'true';
  if (dateless && !draft) {
    if (stamp) {
      writeFileSync(join(POSTS, file), fm ? raw.replace(/^---\n/, `---\ndate: ${TODAY}\n`) : `---\ndate: ${TODAY}\n---\n\n${raw}`);
      console.log(`blog: ${file}: stamped date ${TODAY}`);
    } else {
      console.log(`blog: ${file}: no date, showing ${TODAY} (not saved; CI stamps it on merge, or run with --stamp)`);
    }
  }
  const tagSrc = meta.tags ?? (blogConfig.defaultTags || []).join(',');
  const tags = tagSrc.replace(/^\[|\]$/g, '').split(',').map((t) => t.trim()).filter(Boolean);
  const words = body.replace(/```[\s\S]*?```/g, ' ').split(/\s+/).filter(Boolean).length;
  return {
    ...meta, slug: slugFor(file, meta.title), tags,
    draft,
    minutes: Math.max(1, Math.round(words / 200)),
    html: markdown(body),
  };
}

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const fmtDate = (d) => { const [y, m, day] = d.split('-'); return `${+day} ${MONTHS[+m - 1]} ${y}`; };

// ---------- page chrome (taken from a case study so the sidebar/footer never drift) ----------

const donor = readFileSync(join(ROOT, 'case-studies', 'ledger.html'), 'utf8');
const grab = (re, what) => { const m = donor.match(re); if (!m) throw new Error(`case-studies/ledger.html: ${what} not found`); return m[0]; };

function sidebar(active) {
  let s = grab(/<aside class="sidebar">[\s\S]*?<\/aside>/, 'sidebar');
  s = s.replace(/ active(?=")/g, '').replace(/ aria-current="page"/g, '')
       .replace('<details class="side-group" open>', '<details class="side-group">')
       .replace(/CASE \d+ OF \d+/, 'BLOG')
       .replace(/href="(?!https?:|mailto:|#|\.\.\/)([^"]+)"/g, 'href="../case-studies/$1"');
  if (active) s = s.replace('class="sidebar-nav-item" href="../blog/index.html"', 'class="sidebar-nav-item active" href="../blog/index.html" aria-current="page"');
  return s;
}
const footer = () => grab(/<footer class="site-foot">[\s\S]*?<\/footer>/, 'footer');

function page({ title, description, url, type = 'website', image = `${SITE}/og.png`, body }) {
  return `<!DOCTYPE html>
${MARK}
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(description)}">
<meta property="og:type" content="${type}">
<meta property="og:url" content="${url}">
<meta property="og:image" content="${image}">
<meta name="twitter:card" content="summary_large_image">
<link rel="canonical" href="${url}">
<link rel="alternate" type="application/rss+xml" title="Kai-Bin Wong — Blog" href="${SITE}/blog/feed.xml">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="preload" as="style" href="https://fonts.googleapis.com/css2?family=Familjen+Grotesk:wght@400;500;700&family=Fragment+Mono&display=swap" onload="this.onload=null;this.rel='stylesheet'">
<noscript><link href="https://fonts.googleapis.com/css2?family=Familjen+Grotesk:wght@400;500;700&family=Fragment+Mono&display=swap" rel="stylesheet"></noscript>
<link rel="icon" href="../favicon.svg" type="image/svg+xml">
<link rel="icon" href="../favicon.ico" sizes="32x32">
<link rel="apple-touch-icon" href="../apple-touch-icon.png">
<link rel="stylesheet" href="../style.css">
</head>
<body>

<a class="skip-link" href="#main">Skip to content</a>

${sidebar(true)}

<main class="content" id="main">

${body}

${footer()}

</main>

<script data-goatcounter="https://kaibinw.goatcounter.com/count"
        async src="//gc.zgo.at/count.js"></script>

</body>
</html>
`;
}

// ---------- build ----------

const posts = existsSync(POSTS)
  ? readdirSync(POSTS).filter((f) => f.endsWith('.md') && !f.startsWith('_')).map(parsePost)
      .filter((p) => withDrafts || !p.draft)
      .sort((a, b) => b.date.localeCompare(a.date) || a.slug.localeCompare(b.slug))
  : [];

mkdirSync(OUT, { recursive: true });

// clear previously generated pages (only files carrying our marker) so deleted posts disappear
for (const f of readdirSync(OUT)) {
  if (f.endsWith('.html') && readFileSync(join(OUT, f), 'utf8').includes(MARK)) unlinkSync(join(OUT, f));
}

const kindLine = (p) => [fmtDate(p.date), `${p.minutes} MIN READ`, ...p.tags.map((t) => t.toUpperCase())].join(' · ');

posts.forEach((p, idx) => {
  const older = posts[idx + 1];
  const next = older
    ? `<p class="tc">OLDER POST</p>\n    <a href="${older.slug}.html">${esc(older.title)} →</a>`
    : `<p class="tc">ALL POSTS</p>\n    <a href="index.html">Back to the blog →</a>`;
  writeFileSync(join(OUT, `${p.slug}.html`), page({
    title: `${p.title} — Kai-Bin Wong`,
    description: p.summary,
    url: `${SITE}/blog/${p.slug}.html`,
    type: 'article',
    image: p.image ? (/^https?:/.test(p.image) ? p.image : `${SITE}/blog/${p.image}`) : undefined,
    body: `<div class="case-head" id="top">
  <div class="wrap">
    <a class="back" href="index.html">← Back to the blog</a>
    <h1>${esc(p.title)}</h1>
    <p class="lede">${esc(p.summary)}</p>
    <p class="case-facts"><span><b>DATE</b> ${fmtDate(p.date)}</span><span><b>READ</b> ${p.minutes} min</span>${p.tags.length ? `<span><b>TAGS</b> ${p.tags.map(esc).join(' · ')}</span>` : ''}</p>
  </div>
</div>

<article class="case-body post-body">
  <div class="wrap">
${p.html}
  </div>
</article>

<div class="case-next" id="next">
  <div class="wrap">
    ${next}
  </div>
</div>`,
  }));
});

const list = posts.length
  ? posts.map((p) => `    <article class="work-item">
      <div>
        <h3><a href="${p.slug}.html">${esc(p.title)}</a></h3>
        <p class="work-kind">${esc(kindLine(p))}</p>
      </div>
      <div class="work-body">
        <p>${esc(p.summary)}</p>
        <a class="work-link" href="${p.slug}.html">Read the post</a>
      </div>
    </article>`).join('\n\n')
  : `    <p class="work-kind">NO POSTS YET</p>`;

writeFileSync(join(OUT, 'index.html'), page({
  title: 'Blog — Kai-Bin Wong',
  description: 'Notes from a VFX editor who ships software: pipeline tooling, agentic engineering, and what the cut taught me.',
  url: `${SITE}/blog/`,
  body: `<section aria-labelledby="blog-title">
  <div class="wrap">
    <p class="tc">TC 01:09:30:00 — BLOG</p>
    <h1 class="section-title" id="blog-title">Notes from the cut.</h1>

${list}
  </div>
</section>`,
}));

// homepage: "Latest writing" section, spliced between the markers in index.html
const homePath = join(ROOT, 'index.html');
const home = readFileSync(homePath, 'utf8');
const region = /<!-- blog:latest:start -->[\s\S]*?<!-- blog:latest:end -->/;
if (!region.test(home)) throw new Error('index.html: <!-- blog:latest:start/end --> markers not found');
const latest = posts.slice(0, LATEST).map((p) => `    <article class="work-item">
      <div>
        <h3><a href="blog/${p.slug}.html">${esc(p.title)}</a></h3>
        <p class="work-kind">${esc(kindLine(p))}</p>
      </div>
      <div class="work-body">
        <p>${esc(p.summary)}</p>
        <a class="work-link" href="blog/${p.slug}.html">Read the post</a>
      </div>
    </article>`).join('\n\n');
const homeSection = posts.length ? `<!-- blog:latest:start -->
<section id="writing" aria-labelledby="writing-title">
  <div class="wrap">
    <p class="tc">TC 01:09:30:00 — LATEST WRITING</p>
    <h2 class="section-title" id="writing-title">Notes from the cut.</h2>

${latest}

    <p class="all-posts"><a class="work-link" href="blog/index.html">All posts</a></p>
  </div>
</section>
<!-- blog:latest:end -->` : '<!-- blog:latest:start -->\n<!-- blog:latest:end -->';
const homeNext = home.replace(region, () => homeSection);
if (homeNext !== home) writeFileSync(homePath, homeNext);

const rfc822 = (d) => new Date(`${d}T00:00:00+10:00`).toUTCString();
writeFileSync(join(OUT, 'feed.xml'), `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
<channel>
<title>Kai-Bin Wong — Blog</title>
<link>${SITE}/blog/</link>
<description>Notes from a VFX editor who ships software.</description>
${posts.map((p) => `<item><title>${esc(p.title)}</title><link>${SITE}/blog/${p.slug}.html</link><guid>${SITE}/blog/${p.slug}.html</guid><pubDate>${rfc822(p.date)}</pubDate><description>${esc(p.summary)}</description></item>`).join('\n')}
</channel>
</rss>
`);

console.log(`blog: ${posts.length} post${posts.length === 1 ? '' : 's'} → blog/${posts.map((p) => p.slug + '.html').join(', ') || 'index.html'}`);
